trees/03_bst_insert_search_delete.algorithm:
insert(root, val):
    if root is empty: return a new node(val)
    if val < root.val: root.left = insert(root.left, val)
    else if val > root.val: root.right = insert(root.right, val)
    return root   (equal: a duplicate, nothing changes)
search(root, val):
    node = root
    while node exists and node.val != val: node = node.left if val < node.val else node.right
    return node exists
delete(root, val):
    if root is empty: return empty
    if val < root.val: root.left = delete(root.left, val)
    else if val > root.val: root.right = delete(root.right, val)
    else if root.left is empty: return root.right   (0 or 1 child: the child takes its place)
    else if root.right is empty: return root.left
    else:
        successor = leftmost node of root.right
        root.val = successor.val
        root.right = delete(root.right, successor.val)   (delete the SUCCESSOR's value, not val)
    return root

trees/04_balanced_and_depth.algorithm:
max_depth(node):
    if node is empty: return 0
    return 1 + max(max_depth(node.left), max_depth(node.right))
checked_height(node):
    if node is empty: return 0
    left = checked_height(node.left)
    if left == -1: return -1   (pass the failure straight up, no more work)
    right = checked_height(node.right)
    if right == -1: return -1
    if |left - right| > 1: return -1   (a difference of exactly 1 is still balanced)
    return 1 + max(left, right)
is_balanced(root) = checked_height(root) != -1

linked_lists/03_middle_with_fast_and_slo.algorithm:
slow = head, fast = head
while fast exists and fast.next exists:   (fast needs two more nodes to keep going)
    slow = slow.next
    fast = fast.next.next
return slow   (even length: the second of the two middles)

stacks/05_asteroid_collision.algorithm:
stack = empty
for each size in asteroids:
    alive = true
    while alive and size < 0 and stack not empty and top > 0:   (only right-mover vs left-mover)
        if top < -size: pop   (the top explodes, keep fighting)
        else if top == -size: pop, alive = false   (both explode)
        else: alive = false   (the current one explodes)
    if alive: push size
return stack

monotonic_stacks/02_previous_smaller_ele.algorithm:
answer = [-1] * n, stack = empty   (values increasing bottom -> top)
for i from 0 to n - 1:
    while stack not empty and top >= nums[i]: pop   (>= : equal values are not smaller)
    if stack not empty: answer[i] = top
    push nums[i]
return answer

monotonic_stacks/04_sum_of_subarray_mini.algorithm:
stack = empty, total = 0   (indices; values strictly increasing bottom -> top)
for right from 0 to n:   (right == n is a sentinel that pops everything left)
    while stack not empty and (right == n or nums[top] >= nums[right]):
        middle = pop
        left = new top, or -1 if the stack is empty   (previous strictly smaller index)
        total += nums[middle] * (middle - left) * (right - middle)
    if right < n: push right
return total mod (10^9 + 7)

monotonic_stacks/05_remove_k_digits.algorithm:
stack = empty
for each digit in num:
    while k > 0 and stack not empty and top > digit:   (a bigger digit in front goes first)
        pop, k -= 1
    push digit
while k > 0: pop, k -= 1   (leftover deletions: the stack is sorted, cut its end)
result = stack joined, leading zeros stripped
return "0" if result is empty else result
